/* TRX-BD 44.1 kHz render (trxbd_render_block_44k1), hand-written SHARC+.
 * Generated by gen_trxbd.py.
 *
 * Bit-exact replacement for the native C port (tools/trxbd_sharc/
 * trxbd_sharc.c with native_support.bd_source's shared-scratch effects, and
 * its trxbd_noise_active / transient / phase_prepare / osc_shape / amp_clip
 * helpers), checked by native_gate.py against that build.
 *

 * No quiet shortcut: the Full49 build disables the C port's quiet path, as
 * every block makes the original's shared-scratch stores.
 *  1. Noise: 11 Fibonacci steps (y1c, y1d) times the envelope y1e (decay
 *     y0c), as triples and a final pair; y:k = the noise as 24-bit words (0 when
 *     silent).
 *  2. Transient (y12 counting): a fade of y18 at 9, else the two tables at
 *     y19 (lim(4*2*tb*y2 + 2*ta*y15 + noise)).
 *  3. Main: increments y3*2^18 (/2^17) + y13*y4; oscillator 1 (y16:y17) /4,
 *     oscillator 2 (y1f:y20) as lim(2*sine) into y:$20+k and, with
 *     harmonics y21, mixed in; the asymmetric shaper (y10, y1a, y1b, y14,
 *     y15); amplitude y11 (decay y1), the clipper (y8, y9, curve ya), out =
 *     lim(2*(clipped + x)).
 *
 * Declines (calls the C render) when the transient table offset would read
 * past the tables.
 *
 * Calling convention: R4 = voice, R8 = sine (signed 24-bit words).
 * @TMP@ = a 256-word scratch block owned by the hand-written renders.
 */
.EXTERN trxbd_tables_hw.;
.EXTERN md_shared_scratch_x.;
.EXTERN md_shared_scratch_y.;
.EXTERN md_shared_y20.;
.EXTERN trxbd_render_block_44k1_c.;
.SECTION/SW seg_swco;
.GLOBAL trxbd_render_block_44k1.;
trxbd_render_block_44k1.:
    I7=MODIFY (I7,-0x34)(NW);
    DM (-3,I6) = R8;
    DM (-4,I6) = R9;
    DM (-5,I6) = R10;
    DM (-6,I6) = R11;
    DM (-7,I6) = R12;
    DM (-8,I6) = R13;
    DM (-9,I6) = R14;
    DM (-10,I6) = R15;
    R0 = I0;
    DM (-11,I6) = R0;
    R0 = I1;
    DM (-12,I6) = R0;
    R0 = I2;
    DM (-13,I6) = R0;
    R0 = I3;
    DM (-14,I6) = R0;
    R0 = I4;
    DM (-15,I6) = R0;
    R0 = I5;
    DM (-16,I6) = R0;
    R0 = M4;
    DM (-17,I6) = R0;
    R0 = M0;
    DM (-18,I6) = R0;
    R0 = M1;
    DM (-19,I6) = R0;
    R0 = M2;
    DM (-20,I6) = R0;
    R0 = M3;
    DM (-21,I6) = R0;
    R0 = MR0F;
    DM (-22,I6) = R0;
    R0 = MR1F;
    DM (-23,I6) = R0;
    R0 = MR2F;
    DM (-24,I6) = R0;
    DM (-28,I6) = R8;
    R0 = L0;
    DM (-46,I6) = R0;
    R0 = L1;
    DM (-47,I6) = R0;
    R0 = L2;
    DM (-48,I6) = R0;
    R0 = L3;
    DM (-49,I6) = R0;
    R0 = L4;
    DM (-50,I6) = R0;
    R0 = L5;
    DM (-51,I6) = R0;
    R0 = 0;
    L0 = R0;
    L1 = R0;
    L2 = R0;
    L3 = R0;
    L4 = R0;
    L5 = R0;
    I0 = R4;
    R14 = 0x7FFFFF;
    R15 = 0xFF800000;
    R13 = @SRC@;
    R0 = I0;
    DM (-40,I6) = R0;                   /* voice */
    R12 = -8;
/* ---- guard: the transient table offset --------------------------------------- */
    R0 = DM (0x12,I0);
    R0 = PASS R0;
    IF EQ JUMP .L_g_ok;
    R1 = 10;
    COMP (R0,R1);
    IF EQ JUMP .L_g_ok;                 /* the fade */
    R0 = DM (0x19,I0);
    R1 = 257;
    COMPU (R0,R1);
    IF GE JUMP .L_decline;
.L_g_ok:
/* ---- 1. noise ------------------------------------------------------------------ */
    R8 = DM (0x1E,I0);                  /* noise envelope */
    R1 = DM (0x1C,I0);
    R1 = LSHIFT R1 BY 8;
    R2 = DM (0x1D,I0);
    R2 = LSHIFT R2 BY 8;
    I1 = @TMP@;
    R1 = R1 + R2;
    R0 = R1 * R8 (SSF);
    DM (I1,M6) = R0;
    DM (I1,M6) = R0;
    DM (I1,M6) = R0;
    R2 = R2 + R1;
    R0 = R2 * R8 (SSF);
    DM (I1,M6) = R0;
    DM (I1,M6) = R0;
    DM (I1,M6) = R0;
    R1 = R1 + R2;
    R0 = R1 * R8 (SSF);
    DM (I1,M6) = R0;
    DM (I1,M6) = R0;
    DM (I1,M6) = R0;
    R2 = R2 + R1;
    R0 = R2 * R8 (SSF);
    DM (I1,M6) = R0;
    DM (I1,M6) = R0;
    DM (I1,M6) = R0;
    R1 = R1 + R2;
    R0 = R1 * R8 (SSF);
    DM (I1,M6) = R0;
    DM (I1,M6) = R0;
    DM (I1,M6) = R0;
    R2 = R2 + R1;
    R0 = R2 * R8 (SSF);
    DM (I1,M6) = R0;
    DM (I1,M6) = R0;
    DM (I1,M6) = R0;
    R1 = R1 + R2;
    R0 = R1 * R8 (SSF);
    DM (I1,M6) = R0;
    DM (I1,M6) = R0;
    DM (I1,M6) = R0;
    R2 = R2 + R1;
    R0 = R2 * R8 (SSF);
    DM (I1,M6) = R0;
    DM (I1,M6) = R0;
    DM (I1,M6) = R0;
    R1 = R1 + R2;
    R0 = R1 * R8 (SSF);
    DM (I1,M6) = R0;
    DM (I1,M6) = R0;
    DM (I1,M6) = R0;
    R2 = R2 + R1;
    R0 = R2 * R8 (SSF);
    DM (I1,M6) = R0;
    DM (I1,M6) = R0;
    DM (I1,M6) = R0;
    R1 = R1 + R2;
    R0 = R1 * R8 (SSF);
    DM (I1,M6) = R0;
    DM (I1,M6) = R0;
    R2 = ASHIFT R2 BY R12;
    DM (0x1C,I0) = R2;
    R1 = ASHIFT R1 BY R12;
    DM (0x1D,I0) = R1;
    R0 = DM (0xC,I0);
    R0 = LSHIFT R0 BY 8;
    R0 = R0 * R8 (SSF);
    DM (0x1E,I0) = R0;
    /* y:k = the noise, 0 when silent; the buffer too */
    I1 = @TMP@;
    I2 = md_shared_scratch_y.;
    R8 = PASS R8;
    IF NE JUMP .L_ny;
    R0 = 0;
    LCNTR = 0x20 , DO (PC,.L_nz_end)UNTIL LCE;
    DM (I1,M6) = R0;
    NOP;
.L_nz_end:
    DM (I2,M6) = R0;
    JUMP .L_noise_done;
.L_ny:
    LCNTR = 0x20 , DO (PC,.L_ny_end)UNTIL LCE;
    R0 = DM (I1,M6);
    R0 = LSHIFT R0 BY 8;
    R0 = ASHIFT R0 BY R12;              /* as a canonical 24-bit word */
.L_ny_end:
    DM (I2,M6) = R0;
.L_noise_done:
/* ---- 2. transient ------------------------------------------------------------- */
    I4 = I0;
    I4=MODIFY (I4,0x24)(NW);
    R0 = DM (0x12,I0);
    R0 = PASS R0;
    IF EQ JUMP .L_main;
    R1 = 1;
    R0 = R0 - R1;
    R1 = MAX(R0,R15);
    DM (0x12,I0) = R1;
    R1 = 9;
    COMP (R0,R1);
    IF NE JUMP .L_tables;
    R1 = DM (0x18,I0);
    R2 = 0x73333300;
    LCNTR = 0x20 , DO (PC,.L_fade_end)UNTIL LCE;
    R1 = R1 * R2 (SSF);
    NOP;
.L_fade_end:
    DM (I4,M6) = R1;
    JUMP .L_exit;
.L_tables:
    R0 = DM (0x19,I0);
    R1 = 32;
    R1 = R0 + R1;
    R1 = MIN(R1,R14);
    DM (0x19,I0) = R1;
    R0 = LSHIFT R0 BY 2;
    R1 = trxbd_tables_hw.;
    I3 = R1;
    R1 = DM (0,I3);
    R1 = R1 + R0;
    I2 = R1;                            /* table a + off */
    R1 = DM (1,I3);
    R1 = R1 + R0;
    I3 = R1;                            /* table b + off */
    R2 = DM (2,I0);
    R2 = LSHIFT R2 BY 8;
    R3 = DM (0xF,I0);
    R3 = LSHIFT R3 BY 8;
    I1 = @TMP@;
    LCNTR = 0x20 , DO (PC,.L_tr_end)UNTIL LCE;
    R0 = DM (I3,M6);
    MRF = R2 * R0 (SSF);
    MRF = MRF + R2 * R0 (SSF);          /* 4*tb: four products */
    MRF = MRF + R2 * R0 (SSF);          /* 4*tb: four products */
    MRF = MRF + R2 * R0 (SSF);          /* 4*tb: four products */
    R0 = DM (I2,M6);
    MRF = MRF + R3 * R0 (SSF);
    R0 = MR1F;
    R1 = DM (I1,M6);
    R0 = R0 + R1;
    R0 = MIN(R0,R14);
    R0 = MAX(R0,R15);
.L_tr_end:
    DM (I4,M6) = R0;
    JUMP .L_exit;

/* ---- 3. main ------------------------------------------------------------------- */
.L_main:
    /* increments: P = y13*y4 (exact); inc1 = y3*2^18 + P, inc2 = y3*2^17 + P */
    R0 = DM (0x13,I0);
    R1 = DM (4,I0);
    R5 = R0 * R1 (SSF);
    R6 = R0 * R1 (SSI);
    R2 = FEXT R6 BY 24:7;
    R5 = LSHIFT R5 BY 7;
    R5 = R5 OR R2;                      /* P hi */
    R6 = LSHIFT R6 BY 8;                /* P lo << 8 */
    R0 = DM (3,I0);
    R1 = -6;
    R7 = ASHIFT R0 BY R1;
    R8 = FEXT R0 BY 0:6;
    R8 = LSHIFT R8 BY 26;
    R7 = R7 + R5;
    R8 = R8 + R6;
    R7 = R7 + CI;
    R7 = LSHIFT R7 BY 8;
    R7 = ASHIFT R7 BY R12;        /* inc1 hi (sx24), lo << 8 in R8 */
    R1 = -7;
    R9 = ASHIFT R0 BY R1;
    R10 = FEXT R0 BY 0:7;
    R10 = LSHIFT R10 BY 25;
    R9 = R9 + R5;
    R10 = R10 + R6;
    R9 = R9 + CI;
    R9 = LSHIFT R9 BY 8;
    R9 = ASHIFT R9 BY R12;        /* inc2 hi (sx24), lo << 8 in R10 */
    R0 = DM (0x13,I0);
    R1 = DM (5,I0);
    R1 = LSHIFT R1 BY 8;
    R0 = R0 * R1 (SSF);
    DM (0x13,I0) = R0;
    I1 = md_shared_scratch_x.;
    R0 = DM (0x1A,I0);
    DM (6,I1) = R0;
    R0 = DM (0x1B,I0);
    DM (7,I1) = R0;
    /* oscillators: x(k) = sine1/4 + floor(2*s2*h / 2^28) (h = harmonics y21);
     * y:$20+k = s2 = lim(2*sine2) (both phases masked to 15 bits first) */
    R0 = DM (-28,I6);
    I4 = R0;
    R1 = DM (0x16,I0);
    R2 = DM (0x17,I0);
    R2 = LSHIFT R2 BY 8;
    R3 = DM (0x1F,I0);
    R4 = DM (0x20,I0);
    R4 = LSHIFT R4 BY 8;
    R11 = DM (0x21,I0);
    R11 = LSHIFT R11 BY 4;              /* harmonics << 4 */
    R12 = -2;
    R13 = 0x7FFF;
    I1 = @TMP@;
    I1=MODIFY (I1,0x20)(NW);
    I2 = md_shared_scratch_y.;
    I2=MODIFY (I2,0x20)(NW);
    LCNTR = 0x20 , DO (PC,.L_osc_end)UNTIL LCE;
    R1 = R1 AND R13;
    M4 = R1;
    R2 = R2 + R8;
    R1 = R1 + R7 + CI;
    R0 = DM (M4,I4);
    R0 = ASHIFT R0 BY R12;              /* sine1 / 4 */
    R3 = R3 AND R13;
    M4 = R3;
    R4 = R4 + R10;
    R3 = R3 + R9 + CI;
    R5 = DM (M4,I4);
    R5 = R5 + R5;
    R5 = MIN(R5,R14);
    R5 = MAX(R5,R15);
    R6 = R5 * R11 (SSF) , DM (I2,M6) = R5;
    R0 = R0 + R6;
.L_osc_end:
    DM (I1,M6) = R0;
    R12 = -8;
    R1 = LSHIFT R1 BY 8;
    R1 = ASHIFT R1 BY R12;
    DM (0x16,I0) = R1;
    R3 = LSHIFT R3 BY 8;
    R3 = ASHIFT R3 BY R12;
    DM (0x1F,I0) = R3;
    R2 = ASHIFT R2 BY R12;
    DM (0x17,I0) = R2;
    R4 = ASHIFT R4 BY R12;
    DM (0x20,I0) = R4;
    R0 = DM (0x21,I0);
    R1 = DM (0xE,I0);
    R1 = LSHIFT R1 BY 8;
    R0 = R0 * R1 (SSF);
    DM (0x21,I0) = R0;                  /* harmonics decay */
/* ---- shaper ------------------------------------------------------------------ */
    R1 = DM (0x10,I0);                  /* step */
    R2 = DM (0x1A,I0);                  /* high (start) */
    R3 = DM (0x1B,I0);                  /* low (start) */
    R0 = R1 + R2;
    R0 = MIN(R0,R14);
    R0 = MAX(R0,R15);
    DM (0x1A,I0) = R0;
    R0 = R3 - R1;
    R0 = MIN(R0,R14);
    R0 = MAX(R0,R15);
    DM (0x1B,I0) = R0;
    R4 = R2 + R2;                       /* 2*high */
    R5 = R3 + R3;                       /* 2*low */
    R6 = DM (0x14,I0);                  /* previous high */
    R7 = DM (0x15,I0);                  /* previous low */
    I1 = @TMP@;
    I1=MODIFY (I1,0x20)(NW);
    LCNTR = 0x20 , DO (PC,.L_sh_end)UNTIL LCE;
    R0 = DM (I1,M5);
    R0 = -R0;
    COMP (R0,R4);
    IF GT JUMP .L_sh_hi;
    COMP (R0,R5);
    IF GE JUMP .L_sh_st;
    R0 = R7 + R1;
    R6 = PASS R2;
    R7 = MIN(R0,R14);
    JUMP .L_sh_fold (DB);
    R7 = MAX(R7,R15);
    NOP;
.L_sh_hi:
    R0 = R6 - R1;
    R7 = PASS R3;
    R6 = MIN(R0,R14);
    R6 = MAX(R6,R15);
.L_sh_fold:
    R0 = R0 + R0;
    R0 = MIN(R0,R14);
    R0 = MAX(R0,R15);
.L_sh_st:
    NOP;
.L_sh_end:
    DM (I1,M6) = R0;
    DM (0x14,I0) = R6;
    DM (0x15,I0) = R7;
/* ---- amplitude and clipper ---------------------------------------------------- */
    R1 = DM (0x11,I0);                  /* envelope */
    R2 = DM (1,I0);
    R2 = LSHIFT R2 BY 8;                /* decay << 8 */
    R3 = DM (8,I0);                     /* clip high */
    R4 = DM (9,I0);                     /* clip low */
    R5 = DM (0xA,I0);
    R5 = LSHIFT R5 BY 8;                /* curve << 8 */
    R6 = LSHIFT R3 BY 8;                /* high << 8 */
    R7 = 0;
    R13 = PASS R5;
    I1 = @TMP@;
    I1=MODIFY (I1,0x20)(NW);
    I2 = @TMP@;
    I4 = I0;
    I4=MODIFY (I4,0x24)(NW);
    I3 = md_shared_scratch_x.;
    I3=MODIFY (I3,0x20)(NW);
    I5 = md_shared_scratch_x.;
    I5=MODIFY (I5,0x40)(NW);
    LCNTR = 0x20 , DO (PC,.L_amp_end)UNTIL LCE;
    R0 = DM (I1,M6);
    R8 = DM (I2,M6);
    R0 = R0 + R8;                       /* x + noise (25 bits) */
    R8 = LSHIFT R1 BY 8;
    R0 = R0 * R8 (SSF);
    R0 = MIN(R0,R14);
    R0 = MAX(R0,R15);                   /* xa */
    DM (I3,M6) = R0;
    R1 = R1 * R2 (SSF);                 /* envelope decay */
    COMP (R0,R3);
    IF GE JUMP .L_clip_hi;
    COMP (R0,R4);
    IF LE JUMP .L_clip_lo;
    MR1F = R0;
    MR0F = R7;                          /* ah = xa, al = 0 */
    JUMP .L_curve;
.L_clip_hi:
    R8 = R0 - R3;
    JUMP .L_clip_mul (DB);
    R9 = PASS R3;
    NOP;
.L_clip_lo:
    R8 = R0 - R4;
    R9 = PASS R4;
.L_clip_mul:
    R8 = MIN(R8,R14);
    R8 = MAX(R8,R15);                   /* excess */
    MR1F = R9;
    MR0F = R7;                          /* bound at A1 */
    MRF = MRF + R6 * R8 (SSF);          /* + 2*excess*high */
.L_curve:
    R8 = MR1F;
    R13 = PASS R5;
    IF EQ JUMP .L_clip_out;
    R8 = MIN(R8,R14);
    R8 = MAX(R8,R15);                   /* y0 = lim(ah) */
    R8 = LSHIFT R8 BY 8;
    R9 = ASHIFT R5 BY R12;
    MRF = MRF + R8 * R9 (SSF);
    R8 = MR1F;
.L_clip_out:
    R8 = MIN(R8,R14);
    R8 = MAX(R8,R15);                   /* clipped */
    DM (I5,M6) = R8;
    R8 = R8 + R0;
    R8 = R8 + R8;
    R8 = MIN(R8,R14);
    R8 = MAX(R8,R15);
    NOP;
.L_amp_end:
    DM (I4,M6) = R8;
    DM (0x11,I0) = R1;
    DM (0x18,I0) = R8;
    JUMP .L_exit;
.L_decline:
    /* tail call: the C reference render runs in this render's place, in
     * its caller's frame (not nested under this one: the audio stack is
     * 509 words) */
    R4 = I0;
    R0 = DM (-11,I6);
    I0 = R0;
    R0 = DM (-12,I6);
    I1 = R0;
    R0 = DM (-13,I6);
    I2 = R0;
    R0 = DM (-14,I6);
    I3 = R0;
    R0 = DM (-15,I6);
    I4 = R0;
    R0 = DM (-16,I6);
    I5 = R0;
    R0 = DM (-17,I6);
    M4 = R0;
    R0 = DM (-18,I6);
    M0 = R0;
    R0 = DM (-19,I6);
    M1 = R0;
    R0 = DM (-20,I6);
    M2 = R0;
    R0 = DM (-21,I6);
    M3 = R0;
    R0 = DM (-23,I6);
    MR1F = R0;
    R0 = DM (-24,I6);
    MR2F = R0;
    R0 = DM (-22,I6);
    MR0F = R0;
    R0 = DM (-46,I6);
    L0 = R0;
    R0 = DM (-47,I6);
    L1 = R0;
    R0 = DM (-48,I6);
    L2 = R0;
    R0 = DM (-49,I6);
    L3 = R0;
    R0 = DM (-50,I6);
    L4 = R0;
    R0 = DM (-51,I6);
    L5 = R0;
    R8 = DM (-3,I6);
    R9 = DM (-4,I6);
    R10 = DM (-5,I6);
    R11 = DM (-6,I6);
    R12 = DM (-7,I6);
    R13 = DM (-8,I6);
    R14 = DM (-9,I6);
    R15 = DM (-10,I6);
    I7=MODIFY (I7,0x34)(NW);
    JUMP trxbd_render_block_44k1_c.;
.L_exit:
    R0 = DM (-11,I6);
    I0 = R0;
    R0 = DM (-12,I6);
    I1 = R0;
    R0 = DM (-13,I6);
    I2 = R0;
    R0 = DM (-14,I6);
    I3 = R0;
    R0 = DM (-15,I6);
    I4 = R0;
    R0 = DM (-16,I6);
    I5 = R0;
    R0 = DM (-17,I6);
    M4 = R0;
    R0 = DM (-18,I6);
    M0 = R0;
    R0 = DM (-19,I6);
    M1 = R0;
    R0 = DM (-20,I6);
    M2 = R0;
    R0 = DM (-21,I6);
    M3 = R0;
    R0 = DM (-23,I6);
    MR1F = R0;
    R0 = DM (-24,I6);
    MR2F = R0;
    R0 = DM (-22,I6);
    MR0F = R0;
    R0 = DM (-46,I6);
    L0 = R0;
    R0 = DM (-47,I6);
    L1 = R0;
    R0 = DM (-48,I6);
    L2 = R0;
    R0 = DM (-49,I6);
    L3 = R0;
    R0 = DM (-50,I6);
    L4 = R0;
    R0 = DM (-51,I6);
    L5 = R0;
    R8 = DM (-3,I6);
    R9 = DM (-4,I6);
    R10 = DM (-5,I6);
    R11 = DM (-6,I6);
    R12 = DM (-7,I6);
    R13 = DM (-8,I6);
    R14 = DM (-9,I6);
    R15 = DM (-10,I6);
    I12=DM (M7,I6);
    JUMP (M14,I12) (DB);
    RFRAME;
    NOP;
.ENDSEG;
